/// diagnostics.
class _LoadedScript {
  const _LoadedScript(this.code, this.filename);

  /// Inline code: the source itself is the "path", so eval diagnostics
  /// get a stable pseudo-filename.
  const _LoadedScript.inline(String code) : this(code, '<inline>');

  final String code;
